import{c as t,Z as e,Q as r,j as i,m as l,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"山坡羊·潼关怀古","description":"","frontmatter":{"title":"山坡羊·潼关怀古","author":"张养浩","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/2.md","filePath":"books/shici/yuanqu/2.md"}'),h={name:"books/shici/yuanqu/2.md"};function s(u,a,c,d,p,q){const o=e("PoemNav");return r(),i("div",null,[a[0]||(a[0]=l('<h1 id="山坡羊·潼关怀古" tabindex="-1">山坡羊·潼关怀古 <a class="header-anchor" href="#山坡羊·潼关怀古" aria-label="Permalink to &quot;山坡羊·潼关怀古&quot;">​</a></h1><p><strong>[元] <a href="/authors/zhangyanghao.html">张养浩</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>峰峦如聚，波涛如怒，山河表里潼关路。 望西都，意踌躇。 伤心秦汉经行处，宫阙万间都做了土。 兴，百姓苦；亡，百姓苦。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>山坡羊：曲牌名</li><li>潼关：在今陕西省潼关县北，地势险要，是古代军事要塞</li><li>峰峦如聚：形容华山群峰聚集耸立</li><li>波涛如怒：形容黄河波涛汹涌，如发怒一般</li><li>山河表里：外有黄河，内有华山，形容潼关地势险要</li><li>西都：指长安（今西安），秦汉时期的都城</li><li>踌躇：犹豫不决，此处指心潮起伏、感慨万千</li><li>经行处：经过的地方</li><li>宫阙：宫殿</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>（华山的）山峰从四面八方会聚，（黄河的）波涛像发怒似的汹涌。潼关外有黄河，内有华山，山河雄伟，地势险要。 遥望古都长安，我徘徊不定，思潮起伏。 令人伤心的是经过秦汉宫殿的遗址，昔日万间宫阙如今都化作了尘土。 一朝兴盛，百姓受苦；一朝灭亡，百姓依旧受苦。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首散曲是张养浩晚年的代表作，也是元曲中怀古题材的巅峰之作。作者途经潼关，凭吊古迹，抚今追昔，发出了深沉的历史感慨。</p><p>前三句&quot;峰峦如聚，波涛如怒，山河表里潼关路&quot;，以雄浑的笔触描绘潼关的险要地势，&quot;聚&quot;字写出群山攒立之势，&quot;怒&quot;字写出黄河奔腾之态，气势磅礴。&quot;望西都，意踌躇&quot;，由景入情，引出对历史的追忆。</p><p>&quot;伤心秦汉经行处，宫阙万间都做了土&quot;，写尽历史沧桑，昔日辉煌的秦汉宫阙，如今只剩断壁残垣。最末&quot;兴，百姓苦；亡，百姓苦&quot;两句，以警策之笔点明主旨，揭示了封建社会中无论朝代兴衰，受苦的始终是百姓这一深刻主题，体现了作者对人民疾苦的深切同情，思想境界极高。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>张养浩</strong>（1270年－1329年），字希孟，号云庄，元代著名散曲家。其散曲多写隐逸生活，风格清新自然，也有关心民生疾苦之作。</p><p><a href="/authors/zhangyanghao.html">查看作者详情 →</a></p></blockquote>',15)),n(o)])}const b=t(h,[["render",s]]);export{m as __pageData,b as default};
